package repos

import (
	"time"

	"github.com/brendatamaar/yggdrasil/internal/core"
)

// Input is one tracking request for Decide. It is a closed set. Every input
// carries Now; IDs are generated by the shell and passed in.
type Input interface{ isInput() }

// TrackProject tracks a folder as a project with the picked repos. It is also
// what `ygg seed` sends.
type TrackProject struct {
	NewProjectID core.ProjectID
	Name         string
	Path         CleanPath
	Repos        []Pick
	Actor        Actor
	Now          time.Time
}

// TrackRepos adds or restores repos of an Active project (after a rescan).
type TrackRepos struct {
	ProjectID core.ProjectID
	Repos     []Pick
	Actor     Actor
	Now       time.Time
}

// UntrackRepo hides one repo. Nothing on disk is touched.
type UntrackRepo struct {
	RepoID core.RepoID
	Actor  Actor
	Now    time.Time
}

// UntrackProject hides a project and all its Active repos.
type UntrackProject struct {
	ProjectID core.ProjectID
	Actor     Actor
	Now       time.Time
}

// RenameProject changes a project's name.
type RenameProject struct {
	ProjectID core.ProjectID
	Name      string
	Actor     Actor
	Now       time.Time
}

func (TrackProject) isInput()   {}
func (TrackRepos) isInput()     {}
func (UntrackRepo) isInput()    {}
func (UntrackProject) isInput() {}
func (RenameProject) isInput()  {}
